func TestStore_BuildManifestVersion(t *testing.T) {
	for _, tt := range []struct {
		name            string
		option          []func(*StoreOptions)
		artifactType    string
		configMediaType string
	}{
		{name: "default 1.1", artifactType: MediaTypeFliptFeatures, configMediaType: v1.MediaTypeEmptyJSON},
		{name: "configured 1.0", option: []func(*StoreOptions){WithManifestVersion(oras.PackManifestVersion1_0)}, configMediaType: MediaTypeFliptFeatures},
	} {
		t.Run(tt.name, func(t *testing.T) {
			ctx := context.Background()
			dir := t.TempDir()
			ref, err := ParseReference("flipt://local/bundle:latest")
			require.NoError(t, err)
			store, err := NewStore(zaptest.NewLogger(t), dir, tt.option...)
			require.NoError(t, err)
			src, err := fs.Sub(testdata, "testdata")
			require.NoError(t, err)
			_, err = store.Build(ctx, src, ref)
			require.NoError(t, err)

			target, err := oci.New(path.Join(dir, "bundle"))
			require.NoError(t, err)
			desc, err := target.Resolve(ctx, "latest")
			require.NoError(t, err)
			payload, err := content.FetchAll(ctx, target, desc)
			require.NoError(t, err)
			var manifest v1.Manifest
			require.NoError(t, json.Unmarshal(payload, &manifest))
			assert.Equal(t, tt.artifactType, manifest.ArtifactType)
			assert.Equal(t, tt.configMediaType, manifest.Config.MediaType)
		})
	}
}

